 with duckdb.connect(str(DB),read_only=True) as c:f=c.execute(q).fetchdf();f['code']=f.code.astype(str);x=x.merge(f,on=['code','date'],how='left');x=x[x.vol20<.03];dev=x[x.year.between(2019,2025)];reports=[];sets={}
