 valid=[r for r in reports if r['development_gate_pass']];chosen=max(valid,key=lambda r:(r['development_2019_2025']['geometric_mean'],r['development_2019_2025']['expectancy'])) if valid else None;ceiling=chosen['breadth_ceiling'] if chosen else None;oos=x[(x.year==2026)&(x.breadth<=ceiling)].copy() if ceiling else x.iloc[:0];m=metric(oos);positive=bool(m['n']>=5 and m['expectancy']>0 and (m['profit_factor'] or 0)>1 and m['win_rate']>=.45);root=OUT/f"{datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')}-{AXIS_ID}";root.mkdir(parents=True);oos.to_csv(root/'oos_2026_events.csv',index=False);payload={'schema_version':f'{AXIS_ID}.compare.v1','artifact_role':'authoritative','axis_id':AXIS_ID,'research_phase':'effectiveness_judgment','fixed_evaluation_conditions':{'base_rule':'leaf20 vol20<3% next-open gap<=0 TP8 SL5 H10','changed_axis':'same-day PAN breadth ceiling only','ceilings':CEILINGS,'selection_period':'2019-2025 only','untouched_oos':'2026 complete paths through 2026-07-10','capital_allocation':'not used'},'development_variants':reports,'selection':{'selected_breadth_ceiling':ceiling,'selected':chosen},'oos_2026_metrics':m,'oos_positive_gate_pass':positive,'decision':{'candidate_local_decision':'keep_for_current_selection' if positive else 'drop','authoritative_rollup_decision':'research_only'},'runtime_db_write':False,'production_ranking_changed':False};(root/'compare.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print(root/'compare.json')
